// sites-index worker: proof ledger. Each record is identity +
// trigger + verdict — agents, hooks, skills, and verbs live on
// the domain's own file, read fresh on every open (E1). The DB
// answers "open this?" and "trust this?"; the tab answers
// everything else. Writes happen two ways: seed.mjs (operator,
// sites.json is the seed) and POST /sites/:domain/scan (any
// visitor triggers a probe+upsert — scanning is indexing).
// The worker never takes free-form writes: no auth, no queue,
// no spam surface beyond a canonicalized probe.
export interface Env {
  SITES: D1Database;
}

// Bump when scan logic changes so callers can tell stale
// verdicts from fresh ones.
export const SCAN_VERSION = 3;

export const canonicalHost = (v: string): string | null => {
  const h = v.trim().toLowerCase();
  if (h === "" || h.length > 253) return null;
  if (h !== encodeURI(h)) return null;
  if (h.startsWith("-") || h.endsWith("-") || h.includes("..")) return null;
  if (/^(localhost|localhost\.localdomain)$/.test(h)) return null;
  if (/^\d+\.\d+\.\d+\.\d+$/.test(h)) return null;
  if (!/^[a-z0-9.-]+\.[a-z]{2,}$/.test(h)) return null;
  return h;
};

export interface ProbeFile {
  ok: boolean;
  body: string | null;
  contentType: string;
}

type FetchImpl = (
  url: string,
  init?: { signal?: AbortSignal }
) => Promise<{ ok: boolean; text: () => Promise<string>; headers: { get: (n: string) => string | null } }>;

// Cost guards: 8s per probe, 256KB body cap. Oversize bodies
// read as absent — a huge valid spec is a re-check, not proof.
export const PROBE_TIMEOUT_MS = 8000;
export const MAX_BODY = 262144;

const timedOut = <T>(p: Promise<T>): Promise<T | null> => {
  let t: ReturnType<typeof setTimeout> | undefined;
  try {
    return Promise.race([
      p,
      new Promise<null>((res) => {
        t = setTimeout(() => res(null), PROBE_TIMEOUT_MS);
      }),
    ]);
  } finally {
    if (t !== undefined) clearTimeout(t);
  }
};

const get = async (
  fetchImpl: FetchImpl,
  host: string,
  path: string
): Promise<ProbeFile> => {
  const absent: ProbeFile = { ok: false, body: null, contentType: "" };
  try {
    const r = await timedOut(fetchImpl(`https://${host}${path}`, { signal: AbortSignal.timeout(PROBE_TIMEOUT_MS) }));
    if (!r) return absent;
    const ct = r.headers.get("content-type") ?? "";
    const len = r.headers.get("content-length");
    if (len !== null && /^\d+$/.test(len.trim()) && parseInt(len.trim(), 10) > MAX_BODY) return absent;
    const body = r.ok ? await r.text() : null;
    const cut = body !== null && body.length > MAX_BODY ? body.slice(0, MAX_BODY) : body;
    return { ok: r.ok, body: cut, contentType: ct };
  } catch {
    return absent;
  }
};

const isHtml = (body: string | null): boolean =>
  body !== null && /^\s*</.test(body.slice(0, 2048));

const isJson = (body: string | null): boolean => {
  if (body === null) return false;
  try {
    JSON.parse(body);
    return true;
  } catch {
    return false;
  }
};

export interface SignalResult {
  key: string;
  label: string;
  blurb: string;
  ok: boolean;
}

export interface ScanResult {
  host: string;
  signals: Array<SignalResult>;
  file: { domain: string; description: string } | null;
  native: boolean;
}

// Canonical probe set (§3 of specs/sites-index.md). Every probe
// is presence + honesty: HTTP 200 alone proves nothing (SPA
// fallbacks lie), so bodies are content-checked. fetchImpl is
// injectable so the whole set unit-tests without network.
export const probeAll = async (
  fetchImpl: FetchImpl,
  host: string
): Promise<Omit<ScanResult, "host">> => {
  const [file, llms, skillsIndex, skillMd, apiCatalog, openapi, mcpCard, oauth, agentCard, home] = await Promise.all([
    get(fetchImpl, host, "/.well-known/agent-webmcp.json"),
    get(fetchImpl, host, "/llms.txt"),
    get(fetchImpl, host, "/.well-known/agent-skills/index.json"),
    get(fetchImpl, host, "/skill.md"),
    get(fetchImpl, host, "/.well-known/api-catalog"),
    get(fetchImpl, host, "/openapi.json"),
    get(fetchImpl, host, "/.well-known/mcp/server-card.json"),
    get(fetchImpl, host, "/.well-known/oauth-protected-resource"),
    get(fetchImpl, host, "/.well-known/agent-card.json"),
    get(fetchImpl, host, "/"),
  ]);
  let native = false;
  try {
    const r = await timedOut(
      fetchImpl(`https://webmcp.com/api/v1/lookup?url=https://${host}`, {
        signal: AbortSignal.timeout(PROBE_TIMEOUT_MS),
      })
    );
    if (r?.ok) {
      const j = (await r.text().then((t) => JSON.parse(t) as unknown)) as { supported?: unknown };
      native = j.supported === true;
    }
  } catch {
    native = false;
  }
  const askHtml = home.ok && home.body !== null && /data-context7-ask|context7\.com\/api/i.test(home.body);
  const askLlms = llms.ok && llms.body !== null && /context7/i.test(llms.body);
  const ask = askHtml || askLlms;

  let parsed: { domain?: unknown; description?: unknown } | null = null;
  if (file.ok && isJson(file.body)) {
    const j = JSON.parse(file.body as string) as unknown;
    if (typeof j === "object" && j !== null) parsed = j as Record<string, unknown>;
  }
  const capText = (v: unknown, n: number): string =>
  typeof v === "string" && v.trim() !== "" ? Array.from(v.trim()).slice(0, n).join("") : "";

const fileValid =
    parsed !== null && typeof parsed.domain === "string" && parsed.domain.toLowerCase() === host;
  const fileDesc = fileValid ? capText(parsed.description, 140) : "";

  const signals: Array<SignalResult> = [
    { key: "file", label: "site file", blurb: "owner claim + trigger text", ok: fileValid },
    { key: "llms", label: "llms.txt", blurb: "docs index for agents", ok: llms.ok && !isHtml(llms.body) },
    { key: "skillsIndex", label: "agent skills", blurb: "skill inventory", ok: skillsIndex.ok && isJson(skillsIndex.body) },
    { key: "skillMd", label: "skill.md", blurb: "skill instructions", ok: skillMd.ok && !isHtml(skillMd.body) },
    { key: "apiCatalog", label: "api catalog", blurb: "service catalog", ok: apiCatalog.ok },
    { key: "openapi", label: "openapi.json", blurb: "HTTP API spec", ok: openapi.ok && isJson(openapi.body) },
    { key: "mcp", label: "MCP server card", blurb: "MCP endpoint", ok: mcpCard.ok && isJson(mcpCard.body) },
    { key: "oauth", label: "oauth resource", blurb: "OAuth metadata", ok: oauth.ok },
    { key: "agentCard", label: "agent card", blurb: "agent identity", ok: agentCard.ok && isJson(agentCard.body) },
    { key: "native", label: "native verbs", blurb: "callable page tools", ok: native },
    { key: "ask", label: "ask endpoint", blurb: "queryable docs", ok: ask },
  ];
  return {
    signals,
    file: fileValid ? { domain: host, description: fileDesc } : null,
    native,
  };
};

export interface HasFlags {
  webmcp: boolean;
  skills: boolean;
  api: boolean;
  mcp: boolean;
  auth: boolean;
  ask: boolean;
}

export const hasFromSignals = (
  signals: Array<SignalResult>,
  native: boolean
): HasFlags => {
  const ok = (key: string): boolean => signals.some((s) => s.key === key && s.ok);
  return {
    webmcp: native,
    skills: ok("skillsIndex") || ok("skillMd"),
    api: ok("apiCatalog") || ok("openapi"),
    mcp: ok("mcp"),
    auth: ok("oauth"),
    ask: ok("ask"),
  };
};

// Fresh rows skip probing: the verdict stands for 24h. Cheap
// PK date check before 11 subrequests — this is the herd guard.
export const RESCAN_INTERVAL_MS = 24 * 60 * 60 * 1000;

export const isFresh = (lastVerified: unknown): boolean => {
  if (typeof lastVerified !== "string" || lastVerified === "") return false;
  const t = Date.parse(lastVerified);
  return !Number.isNaN(t) && Date.now() - t < RESCAN_INTERVAL_MS;
};

// Hollow rows never serve cached: a seed without probes must
// heal on first scan, not loop the scanning shell forever.
export const shouldServeCached = (existing: { last_verified?: unknown; signals_json?: unknown } | null): boolean => {
  if (!existing || !isFresh(existing.last_verified)) return false;
  const signals = parse(existing.signals_json, []);
  return Array.isArray(signals) && signals.length > 0;
};

// Keyset paging: cursor is the last domain seen, never an
// offset. D1 bills rows scanned, so OFFSET would charge for
// skipped rows; keyset reads one page. No COUNT anywhere —
// the +1 prefetch row answers hasNext.
export const TAG_COLUMNS: Record<string, string> = {
  webmcp: "has_webmcp",
  skills: "has_skills",
  api: "has_api",
  mcp: "has_mcp",
  auth: "has_auth",
  ask: "has_ask",
};

export const PAGE_DEFAULT = 50;
export const PAGE_MAX = 100;

// One slim row for chips: totals without paging through rows.
export const COUNTS_SQL =
  "SELECT COUNT(*) AS total, " +
  "COALESCE(SUM(has_webmcp), 0) AS webmcp, COALESCE(SUM(has_skills), 0) AS skills, " +
  "COALESCE(SUM(has_api), 0) AS api, COALESCE(SUM(has_mcp), 0) AS mcp, " +
  "COALESCE(SUM(has_auth), 0) AS auth, COALESCE(SUM(has_ask), 0) AS ask FROM sites";

export interface ListQuery {
  sql: string;
  params: Array<unknown>;
  pageSize: number;
}

export const buildListQuery = (opts: {
  tag?: string;
  q?: string;
  cursor?: string | null;
  limit?: number;
}): ListQuery => {
  const where: Array<string> = [];
  const params: Array<unknown> = [];
  if (opts.cursor) {
    where.push("domain > ?");
    params.push(opts.cursor);
  }
  const tag = (opts.tag ?? "").trim().toLowerCase();
  if (tag !== "" && TAG_COLUMNS[tag] !== undefined) {
    where.push(`${TAG_COLUMNS[tag]} = 1`);
  }
  const q = (opts.q ?? "").trim().toLowerCase();
  if (q !== "") {
    const esc = q.replace(/[\\%_]/g, (c) => `\\${c}`);
    where.push("(domain LIKE ? ESCAPE '\\' OR LOWER(description) LIKE ? ESCAPE '\\')");
    params.push(`%${esc}%`, `%${esc}%`);
  }
  const n = Math.min(Math.max(opts.limit ?? PAGE_DEFAULT, 1), PAGE_MAX);
  const sql =
    `SELECT domain, description, description_source, has_json, ` +
    `has_webmcp, has_skills, has_api, has_mcp, has_auth, has_ask, ` +
    `state, state_reason, pinned_ref, last_verified FROM sites` +
    (where.length > 0 ? ` WHERE ${where.join(" AND ")}` : "") +
    ` ORDER BY domain LIMIT ${n + 1}`;
  return { sql, params, pageSize: n };
};

export interface ScanOutcome {
  status: number;
  body: Record<string, unknown>;
}

const json = (v: unknown, status = 200): Response =>
  Response.json(v, {
    headers: { "access-control-allow-origin": "*", "cache-control": "no-store" },
    status,
  });

// GET budget: 300 req/min per IP, isolate-local. POST scans have
// their own budget below. Reads are cheap (keyset page ~51 rows,
// detail is one PK lookup) and the free tier holds ~100k
// list-views/day — this only stops floods, never humans.

interface Row {
  domain: string;
  description: string;
  description_source?: unknown;
  has_json: unknown;
  has_webmcp?: unknown;
  has_skills?: unknown;
  has_api?: unknown;
  has_mcp?: unknown;
  has_auth?: unknown;
  has_ask?: unknown;
  signals_json?: unknown;
  state: string;
  state_reason: unknown;
  pinned_ref: unknown;
  last_verified: unknown;
}

const parse = (s: unknown, fallback: unknown): unknown => {
  if (typeof s !== "string" || s === "") return fallback;
  try {
    return JSON.parse(s) as unknown;
  } catch {
    return fallback;
  }
};

const EMPTY_HAS: HasFlags = { webmcp: false, skills: false, api: false, mcp: false, auth: false, ask: false };

const num = (v: unknown): boolean => v === 1 || v === true;

const hasOf = (r: Row): HasFlags => {
  if (typeof r.has_webmcp === "number" || typeof r.has_webmcp === "boolean") {
    return {
      webmcp: num(r.has_webmcp),
      skills: num(r.has_skills),
      api: num(r.has_api),
      mcp: num(r.has_mcp),
      auth: num(r.has_auth),
      ask: num(r.has_ask),
    };
  }
  return parse(r.has_json, EMPTY_HAS) as HasFlags;
};

const shape = (r: Row): Record<string, unknown> => ({
  domain: r.domain,
  description: r.description,
  source: typeof r.description_source === "string" ? r.description_source : "manual",
  has: hasOf(r),
  state: r.state,
  reason: r.state_reason ?? "",
  proof: { verified: r.last_verified ?? null, ref: r.pinned_ref ?? "" },
});

const shapeDetail = (r: Row): Record<string, unknown> => ({
  ...shape(r),
  signals: parse(r.signals_json, []),
});

const DETAIL_COLS =
  "domain, description, description_source, has_json, " +
  "has_webmcp, has_skills, has_api, has_mcp, has_auth, has_ask, " +
  "signals_json, state, state_reason, pinned_ref, last_verified";

const today = (): string => new Date().toISOString().slice(0, 10);

// Best-effort per-IP throttle: 10 scans/min plus a daily budget
// (2000 scans/day). Isolate-local, so a determined flood still
// lands — but the 24h fresh check behind it keeps floods cheap,
// and D1 writes on free tier simply stop at the daily cap (no
// bill), which is the real backstop. 429s carry Retry-After.
const RATE_WINDOW_MS = 60_000;
const RATE_MAX = 10;
const DAY_MS = 24 * 60 * 60 * 1000;
export const DAY_BUDGET = 2000;

interface Budget {
  windowStart: number;
  windowCount: number;
  dayStart: number;
  dayCount: number;
}

const budgets = new Map<string, Budget>();

export const scanAllowed = (ip: string, now = Date.now()): { ok: boolean; retryAfter: number } => {
  let b = budgets.get(ip);
  if (!b || now - b.dayStart >= DAY_MS) {
    b = { windowStart: now, windowCount: 0, dayStart: now, dayCount: 0 };
    budgets.set(ip, b);
  } else if (now - b.windowStart >= RATE_WINDOW_MS) {
    b.windowStart = now;
    b.windowCount = 0;
  }
  if (b.windowCount >= RATE_MAX) {
    return { ok: false, retryAfter: Math.max(1, Math.ceil((b.windowStart + RATE_WINDOW_MS - now) / 1000)) };
  }
  if (b.dayCount >= DAY_BUDGET) {
    return { ok: false, retryAfter: Math.max(1, Math.ceil((b.dayStart + DAY_MS - now) / 1000)) };
  }
  b.windowCount += 1;
  b.dayCount += 1;
  if (budgets.size > 5000) {
    const k = budgets.keys().next().value;
    if (k !== undefined) budgets.delete(k);
  }
  return { ok: true, retryAfter: 0 };
};

// GET budget lives apart from scans: reads are cheap and the only
// thing worth stopping is a flood burning D1 rows.
const READ_WINDOW_MS = 60_000;
const READ_MAX = 300;

const reads = new Map<string, { start: number; count: number }>();

export const readAllowed = (ip: string, now = Date.now()): { ok: boolean; retryAfter: number } => {
  let r = reads.get(ip);
  if (!r || now - r.start >= READ_WINDOW_MS) {
    r = { start: now, count: 0 };
    reads.set(ip, r);
  }
  if (r.count >= READ_MAX) {
    return { ok: false, retryAfter: Math.max(1, Math.ceil((r.start + READ_WINDOW_MS - now) / 1000)) };
  }
  r.count += 1;
  if (reads.size > 5000) {
    const k = reads.keys().next().value;
    if (k !== undefined) reads.delete(k);
  }
  return { ok: true, retryAfter: 0 };
};

export default {
  async fetch(req: Request, env: Env): Promise<Response> {
    const url = new URL(req.url);
    if (req.method === "POST") {
      const m = /^\/sites\/([^/]+)\/scan$/.exec(url.pathname);
      if (!m) return json({ error: "unknown path" }, 404);
      const host = canonicalHost(decodeURIComponent(m[1] ?? ""));
      if (!host) return json({ error: "bad domain" }, 400);
      const ip = req.headers.get("cf-connecting-ip") ?? "unknown";
      const allowance = scanAllowed(ip);
      if (!allowance.ok) {
        const res = json({ error: "slow down" }, 429);
        res.headers.set("Retry-After", String(allowance.retryAfter));
        return res;
      }
      const existing = await env.SITES.prepare(`SELECT ${DETAIL_COLS} FROM sites WHERE domain = ?`)
        .bind(host)
        .first<Row>();
      if (existing && shouldServeCached(existing)) {
        return json({ site: shapeDetail(existing), version: SCAN_VERSION, cached: true });
      }
      const probed = await probeAll(fetch, host);
      const has = hasFromSignals(probed.signals, probed.native);
      const description =
        probed.file !== null && probed.file.description !== ""
          ? probed.file.description
          : (existing?.description ?? "");
      const source =
        probed.file !== null && probed.file.description !== ""
          ? "file"
          : typeof existing?.description_source === "string"
            ? (existing.description_source as string)
            : "manual";
      await env.SITES.prepare(
        `INSERT INTO sites (domain, description, description_source, scan_version, has_json, has_webmcp, has_skills, has_api, has_mcp, has_auth, has_ask, signals_json, state, state_reason, pinned_ref, last_verified, updated_at, provenance) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'listed', '', '', ?, datetime('now'), 'scan') ON CONFLICT(domain) DO UPDATE SET description=excluded.description, description_source=excluded.description_source, scan_version=excluded.scan_version, has_json=excluded.has_json, has_webmcp=excluded.has_webmcp, has_skills=excluded.has_skills, has_api=excluded.has_api, has_mcp=excluded.has_mcp, has_auth=excluded.has_auth, has_ask=excluded.has_ask, signals_json=excluded.signals_json, last_verified=excluded.last_verified, updated_at=datetime('now')`
      )
        .bind(
          host,
          description,
          source,
          SCAN_VERSION,
          JSON.stringify(has),
          has.webmcp ? 1 : 0,
          has.skills ? 1 : 0,
          has.api ? 1 : 0,
          has.mcp ? 1 : 0,
          has.auth ? 1 : 0,
          has.ask ? 1 : 0,
          JSON.stringify(probed.signals),
          today()
        )
        .run();
      const row = await env.SITES.prepare(`SELECT ${DETAIL_COLS} FROM sites WHERE domain = ?`)
        .bind(host)
        .first<Row>();
      if (!row) return json({ error: "index failed" }, 500);
      return json({ site: shapeDetail(row), version: SCAN_VERSION, cached: false });
    }
    if (req.method !== "GET") return json({ error: "read-only" }, 405);
    const ip = req.headers.get("cf-connecting-ip") ?? "unknown";
    if (url.pathname === "/sites") {
      const tagRaw = url.searchParams.get("tag")?.trim() ?? "";
      const tag = tagRaw.toLowerCase();
      if (tag !== "" && TAG_COLUMNS[tag] === undefined) return json({ error: "bad tag" }, 400);
      const cursorRaw = url.searchParams.get("cursor")?.trim() ?? "";
      let cursor: string | null = null;
      if (cursorRaw !== "") {
        cursor = canonicalHost(cursorRaw);
        if (!cursor) return json({ error: "bad cursor" }, 400);
      }
      const limitRaw = url.searchParams.get("limit")?.trim() ?? "";
      const limit = limitRaw === "" ? PAGE_DEFAULT : Number.parseInt(limitRaw, 10);
      const q = url.searchParams.get("q")?.trim() ?? "";
      const built = buildListQuery({
        tag,
        q,
        cursor,
        limit: Number.isNaN(limit) ? PAGE_DEFAULT : limit,
      });
      const read = readAllowed(ip);
      if (!read.ok) {
        const res = json({ error: "slow down" }, 429);
        res.headers.set("Retry-After", String(read.retryAfter));
        return res;
      }
      const rows = await env.SITES.prepare(built.sql)
        .bind(...built.params)
        .all();
      const found = ((rows.results ?? []) as unknown as Array<Row>).map(shape);
      const hasNext = found.length > built.pageSize;
      const sites = hasNext ? found.slice(0, built.pageSize) : found;
      const nextCursor = hasNext ? (sites[sites.length - 1]?.["domain"] as string) ?? null : null;
      return json({ sites, nextCursor });
    }
    if (url.pathname === "/sites/counts") {
      const read = readAllowed(ip);
      if (!read.ok) {
        const res = json({ error: "slow down" }, 429);
        res.headers.set("Retry-After", String(read.retryAfter));
        return res;
      }
      const row = await env.SITES.prepare(COUNTS_SQL).first<Record<string, unknown>>();
      const n = (k: string): number => (typeof row?.[k] === "number" ? (row[k] as number) : 0);
      return json({
        counts: {
          total: n("total"),
          webmcp: n("webmcp"),
          skills: n("skills"),
          api: n("api"),
          mcp: n("mcp"),
          auth: n("auth"),
          ask: n("ask"),
        },
      });
    }
    const m = /^\/sites\/([^/]+)$/.exec(url.pathname);
    if (m) {
      const host = canonicalHost(m[1] ?? "");
      if (!host) return json({ error: "bad domain" }, 400);
      const read = readAllowed(ip);
      if (!read.ok) {
        const res = json({ error: "slow down" }, 429);
        res.headers.set("Retry-After", String(read.retryAfter));
        return res;
      }
      const row = await env.SITES.prepare(`SELECT ${DETAIL_COLS} FROM sites WHERE domain = ?`)
        .bind(host)
        .first<Row>();
      if (!row) return json({ error: "not listed" }, 404);
      return json({ site: shapeDetail(row), version: SCAN_VERSION });
    }
    if (url.pathname === "/health") return json({ ok: true });
    if (url.pathname === "/") {
      return json({
        name: "agent-webmcp-sites",
        description: "Agent-ready site verdicts: identity, trigger, proof. Scans persist.",
        endpoints: ["/sites", "/sites/:domain", "POST /sites/:domain/scan", "/health"],
      });
    }
    return json({ error: "unknown path" }, 404);
  },
};
